SourceCode.Declaration:
/// <summary>
/// Table containing device capabilities
/// </summary>
public class TFMDeviceCapabilities extends common
{
}

Method.Source:
/// <summary>
/// Does the device ID have any capabilities recorded in the system
/// </summary>
/// <param name = "_deviceId">Device ID</param>
/// <returns></returns>
public static boolean existDevice(str _deviceId)
{
    TFMDeviceCapabilities deviceCapabilities;
    select firstonly RecId from deviceCapabilities
        where deviceCapabilities.DeviceId == _deviceId;

    return deviceCapabilities.RecId != 0;
}

/// <summary>
/// Get the value of the capability for the given device, domain, and attribute combination.
/// </summary>
/// <param name = "_deviceId">Device ID</param>
/// <param name = "_domain">Domain in request structure</param>
/// <param name = "_attribute">Attribute name</param>
/// <returns></returns>
public static str getValue(str _deviceId, str _domain, str _attribute)
{
    TFMDeviceCapabilities deviceCapabilities;
    select firstonly Value from deviceCapabilities
        where deviceCapabilities.DeviceId == _deviceId
        && deviceCapabilities.DomainName == _domain
        && deviceCapabilities.Key == _attribute;

    return deviceCapabilities.Value;
}

/// <summary>
/// Creates or updates a record in the TFMDeviceCapabilities table for the given device, domain, and attribute combination.
/// </summary>
/// <param name = "_deviceId">Device ID</param>
/// <param name = "_domain">Domain in request structure</param>
/// <param name = "_attribute">Attribute name</param>
/// <param name = "_value">Attribute value</param>
public static void createOrUpdateCapabilities(str _deviceId, str _domain, str _attribute, str _value)
{
    TFMDeviceCapabilities deviceCapabilities;
    select firstonly forupdate deviceCapabilities
        where deviceCapabilities.DeviceId == _deviceId
        && deviceCapabilities.DomainName == _domain
        && deviceCapabilities.Key == _attribute;

    ttsbegin;
    if(!deviceCapabilities)
    {
        deviceCapabilities.DeviceId = _deviceId;
        deviceCapabilities.DomainName = _domain;
        deviceCapabilities.Key = _attribute;
    }
    deviceCapabilities.Value = _value;
    deviceCapabilities.write();
    ttscommit;
}
